import sqlite3

app = Flask(__name__)

@app.route('/lookup')
def lookup():
    username = request.args.get('username')
    if not username:
        return "No username provided", 400

    conn = sqlite3.connect('example.db')
    cursor = conn.cursor()
    cursor.execute("SELECT * FROM users WHERE username=?", (username,))
    user = cursor.fetchone()
    conn.close()

